const jobNames:Record<string,string>={transcribe:'Transcribing',transcribe_live:'Transcribing live',index:'Preparing search',summarize:'Creating summary'};
type Page='home'|'library'|'studio'|'search'|'settings'|'detail';
const date=(s:number)=>new Date(s*1000).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
// VERSION is the single source of the app version (scripts/version.py keeps the other copies in step).
const version=versionFile.trim();
const mediaExtensions=['wav','mp3','flac','ogg','m4a','aac','opus','mp4','mkv','webm','mov'];
type SummaryProfile='e2b'|'e4b';
const summaryIds:Record<SummaryProfile,string>={e2b:'summary_e2b',e4b:'summary_e4b'};
// Gemma 3 1B was removed in 0.1.8; any other saved choice means the default, E2B.
const summaryProfile=(value?:string):SummaryProfile=>value==='e4b'?'e4b':'e2b';
type Appearance='system'|'light'|'dark';
const appearanceOf=(value?:string|null):Appearance=>value==='light'||value==='dark'?value:'system';
const readAppearance=():Appearance=>{try{return appearanceOf(localStorage.getItem('voxloom-appearance'));}catch{return 'system';}};
// index.html applies a saved choice before the stylesheet, so the first paint matches. The floating recorder hears the same storage key.
const applyAppearance=(value:Appearance)=>{const root=document.documentElement;if(value==='system')delete root.dataset.theme;else root.dataset.theme=value;try{localStorage.setItem('voxloom-appearance',value);}catch{/* The choice still applies in this window. */}};
const summaryModel=(id:string)=>id.startsWith('summary');
const notesHeadings:Record<string,[string,string]>={counselling:['Session notes.','Themes, concerns and agreed next steps from your transcript. Review before sharing.'],service:['Conversation notes.','Reason for contact, support discussed and follow-up from your transcript. Review before sharing.'],meeting:['Meeting notes.','Topics, decisions and next steps from your transcript. Review before sharing.'],custom:['Notes.','Written to your instructions from the transcript. Review before sharing.']};
const styleHelp:Record<string,string>={counselling:'Main concerns, feelings and experiences, strengths and supports, and agreed next steps. No diagnosis, labels or advice that was not said.',service:'Reason for contact, information shared, support or options discussed, and agreed follow-up.',meeting:'Discussion points, decisions, action items and next steps.',custom:'Describe what the notes should contain and how to organise them.'};
const size=(bytes:number)=>bytes>=1e9?`${(bytes/1e9).toFixed(2)} GB`:`${Math.round(bytes/1e6)} MB`;

