  const [detail,setDetail]=useState<Detail|null>(null);const [selected,setSelected]=useState('');const [tab,setTab]=useState('transcript');const [trackId,setTrackId]=useState('');const [playAt,setPlayAt]=useState(0);const [playing,setPlaying]=useState(false);const [position,setPosition]=useState(0);const autoplay=useRef(false);
  const [error,setError]=useState('');const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const [libraryQuery,setLibraryQuery]=useState('');const [sort,setSort]=useState('newest');const [recordTitle,setRecordTitle]=useState('');
  const [query,setQuery]=useState('');const [searchMode,setSearchMode]=useState('combined');const [results,setResults]=useState<Hit[]>([]);const [searched,setSearched]=useState(false);const [sourceFilter,setSourceFilter]=useState('all');const [meetingFilter,setMeetingFilter]=useState('all');const [after,setAfter]=useState('');const [answer,setAnswer]=useState('');
  const [settings,setSettings]=useState<Record<string,string>>({});const [appearance,setAppearance]=useState<Appearance>(readAppearance);const appearanceTouched=useRef(false);const [models,setModels]=useState<Model[]>([]);const [setup,setSetup]=useState(false);const [includeSummary,setIncludeSummary]=useState(true);const [setupSummaryProfile,setSetupSummaryProfile]=useState<SummaryProfile>('e2b');const [setupBusy,setSetupBusy]=useState(false);const [progress,setProgress]=useState<Record<string,{status:string;received?:number;total?:number}>>({});
  const [runtime,setRuntime]=useState<{inference:boolean;whisper:boolean;llama:boolean;disk_free_bytes:number}|null>(null);
  const [diagnostics,setDiagnostics]=useState<unknown>(null);const [edit,setEdit]=useState<Segment|null>(null);const [confirmDelete,setConfirmDelete]=useState(false);const [confirmRemove,setConfirmRemove]=useState<Model[]|null>(null);
  const [activityOpen,setActivityOpen]=useState(false);const [allDone,setAllDone]=useState(false);const lastWork=useRef<string[]>([]);const activityRef=useRef<HTMLDivElement>(null);
  const audio=useRef<HTMLAudioElement>(null);const selectedRef=useRef(selected);selectedRef.current=selected;
  const act=useCallback(async(fn:()=>Promise<unknown>)=>{setError('');setBusy(true);try{await fn();}catch(e){setError(String(e));}finally{setBusy(false);}},[]);
