  useEffect(()=>{if(audio.current&&trackId){const t=detail?.tracks.find(t=>t.id===trackId);audio.current.currentTime=Math.max(0,(playAt-(t?.offset_ms||0))/1000);if(autoplay.current&&audio.current.readyState>0){autoplay.current=false;void audio.current.play().catch(()=>setNotice('Press Play to listen.'));}}},[trackId,playAt,detail?.meeting.id]);
  const chooseMeeting=async(id:string,at=0,source?:string)=>{const d=await api<Detail>('detail',{id});setSelected(id);setDetail(d);const t=d.tracks.find(t=>(!source||t.source===source)&&t.offset_ms<=at&&(!d.tracks.some(n=>n.source===t.source&&n.offset_ms>t.offset_ms&&n.offset_ms<=at)))||d.tracks[0];setTrackId(t?.id||'');setPlayAt(at);setPosition(at);autoplay.current=!!source||at>0;setTab('transcript');setPage('detail');};
  const importFile=()=>act(async()=>{const path=await open({multiple:false,filters:[{name:'Audio & video',extensions:mediaExtensions}]});if(typeof path!=='string')return;const result=await api<{id:string}>('import',{path});await refresh();await chooseMeeting(result.id);setNotice('Imported. Your audio is ready to play; available offline tools will prepare the transcript and search.');});
  const enqueue=(kind:string,id=selected)=>act(async()=>{await api('enqueue',{id,kind});setNotice(`${kind==='summarize'?'Summary':kind==='index'?'Audio + text indexing':'Transcription'} queued. Its progress shows at the top; click it to cancel.`);await refresh();});
