  const compact=(value:boolean)=>act(()=>api('window_mode',{compact:value}));
  const quit=()=>act(()=>api('quit'));
  const search=()=>act(async()=>{const hits=await api<Hit[]>('search',{query,mode:searchMode,filter:{source:sourceFilter,meeting_id:meetingFilter,after:after?Math.floor(new Date(after).getTime()/1000):undefined}});setResults(hits);setSearched(true);setAnswer('');});
  const setupModels=(setupMode:string,model?:string)=>act(async()=>{let path: string|null=null;if(setupMode==='import'){const selected=await open({multiple:false,title:'Import a pinned local model',filters:[{name:'Local model',extensions:['bin','litertlm','gguf']}]});if(typeof selected!=='string')return;path=selected;}
    await api('setup',{mode:setupMode,core_only:!includeSummary,model,path});setSetupBusy(true);setNotice(setupMode==='download'?'Downloading only the models you selected. Cancel at any time.':'Checking model integrity locally…');});
  const setupRuntime=(offline=false)=>act(async()=>{let wheelhouse:string|null=null;if(offline){const selected=await open({directory:true,multiple:false,title:'Choose a folder of offline runtime wheels'});if(typeof selected!=='string')return;wheelhouse=selected;}await api('setup',{mode:'runtime',wheelhouse});setSetupBusy(true);setNotice('Setting up the local search runtime. No recordings or transcripts are sent.');});
