  const liveOn=!!capture&&!capture.paused&&models.some(m=>(m.id==='whisper'||m.id==='whisper_accurate')&&m.present);const extraJobs=liveOn?workJobs.length:workJobs.length-1;
  const showActivity=liveOn||workJobs.length>0||failedJobs.length>0||allDone;
